// OTOMATİK ÜRETİLİR (_tasarim/araclar/karakter-gom.py) — elle düzenleme. GPT "VAHRAN Claude Devir" karakter paketi:
// 16 tam boy 2B seçim görseli (512×768; anahtar ırk.sınıf.cinsiyet) + 20 yüz portresi (yuz.ırk.cinsiyet.yüz). SANAT ONAYI BEKLİYOR.
// BOX: görünür alfa sınırı [x0, y0, x1, y1] (512×768 tuvalde) — ayak hizası y1.
export const BOX = {"sancak.mage.m":[22,254,491,745],"sancak.mage.f":[22,222,491,745],"sancak.priest.m":[21,181,491,745],"sancak.priest.f":[23,151,491,745],"sancak.warrior.m":[10,91,503,749],"sancak.warrior.f":[12,0,504,750],"sancak.rogue.m":[21,166,491,745],"sancak.rogue.f":[21,134,489,745],"ocak.mage.m":[22,262,491,744],"ocak.mage.f":[2,2,511,766],"ocak.priest.m":[21,220,491,744],"ocak.priest.f":[21,212,491,745],"ocak.warrior.m":[5,3,465,760],"ocak.warrior.f":[21,140,491,745],"ocak.rogue.m":[22,237,491,745],"ocak.rogue.f":[21,225,491,745]};
const D = {
"sancak.mage.m":"",
"sancak.mage.f":"",
"sancak.priest.m":"",
"sancak.priest.f":"",
"sancak.warrior.m":"",
"sancak.warrior.f":"",
"sancak.rogue.m":"",
"sancak.rogue.f":"",
"ocak.mage.m":"",
"ocak.mage.f":"",
"ocak.priest.m":"",
"ocak.priest.f":"",
"ocak.warrior.m":"",
"ocak.warrior.f":"",
"ocak.rogue.m":"",
"ocak.rogue.f":"",
"yuz.sancak.m.0":"",
"yuz.sancak.m.1":"",
"yuz.sancak.m.2":"",
"yuz.sancak.m.3":"",
"yuz.sancak.m.4":"",
"yuz.sancak.f.0":"",
"yuz.sancak.f.1":"",
"yuz.sancak.f.2":"",
"yuz.sancak.f.3":"",
"yuz.sancak.f.4":"",
"yuz.ocak.m.0":"",
"yuz.ocak.m.1":"",
"yuz.ocak.m.2":"",
"yuz.ocak.m.3":"",
"yuz.ocak.m.4":"",
"yuz.ocak.f.0":"",
"yuz.ocak.f.1":"",
"yuz.ocak.f.2":"",
"yuz.ocak.f.3":"",
"yuz.ocak.f.4":"",
};
const U = {};
const url = k => { if (U[k]) return U[k]; const s = D[k]; if (!s) return null;
  try { const b = atob(s), a = new Uint8Array(b.length); for (let i = 0; i < b.length; i++) a[i] = b.charCodeAt(i); return (U[k] = URL.createObjectURL(new Blob([a], { type: "image/webp" }))); }
  catch { return (U[k] = "data:image/webp;base64," + s); } };
const r_ = r => (r === 'ocak' ? 'ocak' : 'sancak'), g_ = g => (g === 'f' ? 'f' : 'm');
// Tam boy: ırk (sancak|ocak), sınıf (warrior|rogue|mage|priest), cinsiyet (m|f)
export const sprKey = (race, cls, g) => `${r_(race)}.${D[`${r_(race)}.${cls}.m`] ? cls : 'warrior'}.${g_(g)}`;
export const sprUrl = (race, cls, g) => url(sprKey(race, cls, g));
export const sprBox = (race, cls, g) => BOX[sprKey(race, cls, g)];
// Yüz portresi: oyundaki yüz seçeneği (shared/gorunus.js FACES, 0-4) ile birebir
export const yuzUrl = (race, g, face) => url(`yuz.${r_(race)}.${g_(g)}.${Math.max(0, Math.min(4, face | 0))}`);
export const KEYS = Object.keys(D);
